func runSearch() {
    let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else {
        clearResults()
        return
    }
    guard !(isSearching && submittedConfiguration == requestConfiguration) else { return }
    stopEngineWork()
    submittedConfiguration = requestConfiguration
    configurationInvalidated = false
    hasSubmitted = true
    wasCancelled = false
    errorMessage = nil
    hasMore = false
    guard availableScopes.contains(scope) else {
        results = []
        errorMessage = "שיטת חיפוש זו אינה נתמכת במקור הפעיל. בחרו שיטה זמינה."
        return
    }
    if let message = optionsValidationMessage {
        results = []
        errorMessage = message
        return
    }
    submissionRevision += 1
    acceptsEngineUpdates = true
    resultKitabFilter = ""
    allowsAutomaticPaging = true
    #if os(iOS)
    searchViewModel?.addToHistory(trimmed)
    #endif
    #if DEBUG
    NSLog("[GlobalSearch] submit revision=%d generation=%d backend=%@ scope=%@", submissionRevision, searchGeneration,
          BackendCoordinator.shared.activeBackendID.rawValue, scope.rawValue)
    #endif

    if isSefaria {
        runSefariaSearch(query: trimmed)
    } else if scope == .zayit {
        runZayitSearch(query: trimmed)
    } else {
        runOtzariaSearch(query: trimmed)
    }
}

    func loadHistory() {
        searchHistory = UserDefaults.standard.stringArray(forKey: historyKey) ?? []
    }

    func addToHistory(_ query: String) {
        let trimmed = query.trimmingCharacters(in: .whitespaces)
        guard !trimmed.isEmpty else { return }
        var current = searchHistory
        current.removeAll { $0 == trimmed }
        current.insert(trimmed, at: 0)
        if current.count > 20 {
            current = Array(current.prefix(20))
        }
        searchHistory = current
        UserDefaults.standard.set(current, forKey: historyKey)
    }

    func removeFromHistory(_ query: String) {
        var current = searchHistory
        current.removeAll { $0 == query }
        searchHistory = current
        UserDefaults.standard.set(current, forKey: historyKey)
    }
}

.onAppear {
    observeNativePresentation()
    session.searchViewModel = viewModel
    if !session.availableScopes.contains(session.scope), !session.hasSubmitted {
        session.scope = session.availableScopes.first ?? session.scope
    }
    if session.selectedBookIds != viewModel.selectedBookIds {
        session.selectedBookIds = viewModel.selectedBookIds
    }
    if BackendCoordinator.shared.usesNativeMaktabahDataPath {
        ftsManager.checkNeedsMigration()
    }
}
.onChange(of: nativeRoutingSession.map(ObjectIdentifier.init), initial: true) { _, _ in
    observeNativePresentation()
}
.onDisappear {
    nativeRoutingSession?.removeSearchPresentation(owner: nativePresentationOwner)
}
